INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(13101, 'Psalms 15:2', 'Psalms', 15, 2, '&nbsp;هغه څوک چې وى بې‌عېبه او ښۀ کارونه کوى، او د زړۀ د اخلاص نه رښتيا خبرې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13102, 'Psalms 15:3', 'Psalms', 15, 3, '&nbsp;څوک چې نۀ کړى غېبتونه او په ګاونډى نۀ کوئ ظلمونه او نۀ په خپلو دوستانو باندې بد وائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13103, 'Psalms 15:4', 'Psalms', 15, 4, '&nbsp;چې منکرانو ته سپک ګورى او د مالِک خُدائ د وفادارانو قدر کوى، کۀ هر څومره ورته سخته وى خو بيا هم مدام ټينګ ولاړ وى په خپل عهد او پيمان،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13104, 'Psalms 15:5', 'Psalms', 15, 5, '&nbsp;د قرض په بدل کښې چې څوک نۀ وى سود خواران او څوک چې د بې‌ګناه خلاف رشوت نۀ قبلوى. نو داسې چې څوک کوى هغه به قائم وى مدام.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13105, 'Psalms 16:1', 'Psalms', 16, 1, '&nbsp;اے پاکه خُدايه، ما وساته په خپل امان، پناه مې راوړه تا ته او شه مې نګهبان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13106, 'Psalms 16:2', 'Psalms', 16, 2, '&nbsp;ما ووئيل مالِک خُدائ ته، ”تۀ زما مالِک يې، زما دغه ټول برکتونه او ښېګړې له تا نه دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13107, 'Psalms 16:3', 'Psalms', 16, 3, '&nbsp;په زمکه باندې ټول مؤمنان دى رښتينې شريفان، په دوئ کښې زما خوشحالى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13108, 'Psalms 16:4', 'Psalms', 16, 4, '&nbsp;خو اخته به شى هغه خلق په خفګان چې د خُدائ نه غېر منى نور خُدايان. نۀ به اخلم برخه د هغوئ په قربانيانو نۀ به واخلم د هغوئ د معبودانو نومونه په زبان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13109, 'Psalms 16:5', 'Psalms', 16, 5, '&nbsp;تۀ يې اے مالِکه خُدايه زما ټول نصيب او برکتونه، او زما د هر څيز ساتونکے يې تۀ په خپله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13110, 'Psalms 16:6', 'Psalms', 16, 6, '&nbsp;تا ما له په برخه کښې راکړى دى ښۀ ځايونه، بې‌شکه چې عجيبه دى ستا ميراثونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13111, 'Psalms 16:7', 'Psalms', 16, 7, '&nbsp;زۀ به د هغه مالِک خُدائ ادا کړم ثناء او صِفتونه څوک چې ما له کوى هدايتونه، خپل زړۀ راته د شپې هم کوى لارښودنه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13112, 'Psalms 16:8', 'Psalms', 16, 8, '&nbsp;مالِک خُدائ همېشه راسره دے زۀ په دې پوهېږم. هغه په خوا کښې راسره دے نو زۀ به نۀ غورزېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13113, 'Psalms 16:9', 'Psalms', 16, 9, '&nbsp;نو ځکه مې زړۀ خوشحاله دے خوشحالېږم، ژوند کوم او په امان کښې اوسېږم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13114, 'Psalms 16:10', 'Psalms', 16, 10, '&nbsp;زما روح به تۀ پرې نۀ ږدې په عالمِ ارواح کښې، خاورې کېدو ته به پرې نۀ ږدې تۀ خپل قُدوس.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13115, 'Psalms 16:11', 'Psalms', 16, 11, '&nbsp;تۀ به ما ته ‎د ژوندون لارښودنه وکړې، د خپل حضور خوند به ما له راکړې، تا سره د تل ژوندون خوشحالى به ما له راکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13116, 'Psalms 17:1', 'Psalms', 17, 1, '&nbsp;اے مالِکه خُدايه، زما د اِنصاف درخواستونه واوره، زما د مدد کولو فريادونه واوره. زما دُعا ته ورکړه پاملرنه، په صادقو شونډو چې کړمه سوالونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13117, 'Psalms 17:2', 'Psalms', 17, 2, '&nbsp;ما بې‌ګناه ثابت کړه، ځکه ټول تا ته څرګند دى چې ښۀ کوى کارونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13118, 'Psalms 17:3', 'Psalms', 17, 3, '&nbsp;تا په شپه کښې زما د خيالونو او د زړۀ وکړل امتحانونه، پس د امتحان نه دې په ما کښې پېدا نۀ کړل غلط کارونه، اراده زما پخه ده په ژبه نۀ کړم ګناهونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13119, 'Psalms 17:4', 'Psalms', 17, 4, '&nbsp;ما منلى دى ټول ستا حُکمونه کوم چې ما ساتى د ظالمانو د لارو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13120, 'Psalms 17:5', 'Psalms', 17, 5, '&nbsp;زۀ همېشه ستا په لاره يم روان، زۀ ستا نه نۀ يم اوړېدلے، يم دې پېروکار.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13121, 'Psalms 17:6', 'Psalms', 17, 6, '&nbsp;زۀ دُعا کومه تا ته، اے خُدايه، تۀ به راکړې جوابونه، کله چې دُعا کوم غوږ ونيسه ما ته قبول مې کړه سوالونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13122, 'Psalms 17:7', 'Psalms', 17, 7, '&nbsp;ما ته د خپلې لوئې مينې خواږۀ راوښايه، په خپل قُدرت دوئ بچ کوې تۀ له دشمنه څوک چې پناه غواړى له تا نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13123, 'Psalms 17:8', 'Psalms', 17, 8, '&nbsp;وساته ما داسې لکه ستا د سترګو تور په شان، د خپل وزرونو په سورى ما پټ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13124, 'Psalms 17:9', 'Psalms', 17, 9, '&nbsp;د بدعملو خلقو نه ما وساته چې په ما کوى حملې، ما وساته د بې‌رحمه دشمنانو نه چې يې واچولې ګېرې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13125, 'Psalms 17:10', 'Psalms', 17, 10, '&nbsp;کلک کړى دى هغوئ خپل بې‌رحمه زړونه، واوره په خپله د هغوئ د لافو ډک کلامونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13126, 'Psalms 17:11', 'Psalms', 17, 11, '&nbsp;زما نه ګېرچاپېره شوى دى، زۀ يې نيولے يم، کوى دوئ د دې انتظار چې زمکې ته مې راوولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13127, 'Psalms 17:12', 'Psalms', 17, 12, '&nbsp;زما د وژلو په تلاش کښې دى دوئ لکه د اوږى ازمرى په شان، لکه د خپل ښکار په طمع پټ ناست چې وى زمرے ځوان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13128, 'Psalms 17:13', 'Psalms', 17, 13, '&nbsp;اے مالِکه، راپاڅه، ودرېږه د دوئ خلاف، په ګوډو کړه شريران، ما د خپلې تُورې په زور له بدعملو نه بچ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13129, 'Psalms 17:14', 'Psalms', 17, 14, '&nbsp;اے مالِکه خُدايه، د خپل لاس په طاقت دې تباه کړه هغه خلق، څوک چې په دې دُنيا لټوى خپل اجرونه. خو په خېټه ماړۀ کړه خپل غوره شوى بنيادمان، د دوئ اولاد سره دې وى ډېر مالونه، په ميراث کښې دې پاتې شى ورته مال او دولتونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13130, 'Psalms 17:15', 'Psalms', 17, 15, '&nbsp;ځکه زۀ يمه صادق ستا مخ به ووينم، زۀ چې کله راپاڅم ستا ديدن به وکړم په ليدو ستا به مطمئن شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13131, 'Psalms 18:1', 'Psalms', 18, 1, '&nbsp;اے مالِکه خُدايه تا سره مينه کوم تۀ په خپله زما زور او طاقت يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13132, 'Psalms 18:2', 'Psalms', 18, 2, '&nbsp;مالِک خُدائ ګټ دے زما، قلعه ده زما، او خلاصوونکے دے زما، زما خُدائ ګټ دے زما، په چا کښې چې ما خپل حفاظت موندلے دے. هغه دے ډال زما، هغه زور چې بچ کوى ما، او د حفاظت پناه ګاه ده زما.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13133, 'Psalms 18:3', 'Psalms', 18, 3, '&nbsp;مالِک خُدائ ته مې وکړل آوازونه څوک چې لائق دے د ثناء صِفتونو، او هم هغه په خپله مې د دشمنانو نه بچ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13134, 'Psalms 18:4', 'Psalms', 18, 4, '&nbsp;زۀ د مرګ په پړو کښې راګېر شوے يم، د بربادۍ طوفان مې د سر دپاسه تېر شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13135, 'Psalms 18:5', 'Psalms', 18, 5, '&nbsp;ګېرچاپېره رانه تاو دى د قبر زنځيرونه، زما په لار کښې مرګى خپل دامونه غوړولى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13136, 'Psalms 18:6', 'Psalms', 18, 6, '&nbsp;په سختۍ کښې خپل مالِک ته کړمه آوازونه، د مدد دپاره ما خپل خُدائ ته وکړل آوازونه. د خپل مقدس ځايه هغۀ واورېدل زما آوازونه، د هغۀ تر غوږو ورسېدل زما فريادونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13137, 'Psalms 18:7', 'Psalms', 18, 7, '&nbsp;زمکه باندې زلزله راغله ولړزېده، د ټولو غرونو بنيادونه وخوځېدل، زلزله ځکه پرې راغله چې هغه په غصه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13138, 'Psalms 18:8', 'Psalms', 18, 8, '&nbsp;د هغۀ د پوزې او سپېږمو نه لوږې راووتل، بل سکارۀ ترې نه روان وو يروونکى لمبه يې د خولې راووتله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13139, 'Psalms 18:9', 'Psalms', 18, 9, '&nbsp;هغه لاندې ترې راکوز شولو وشلول يې آسمانونه، د هغۀ د پښو د لاندې تورې وريځې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13140, 'Psalms 18:10', 'Psalms', 18, 10, '&nbsp;والوتو هغه په وزرو والا مخلوق سور شولو، هغه د هوا په وزرو سور شولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13141, 'Psalms 18:11', 'Psalms', 18, 11, '&nbsp;هغۀ د خپله ځانه ګېرچاپېره تيارۀ تاو کړله، د باران نه ډکه وريځ يې د خپل ځان نه راتاوه کړله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13142, 'Psalms 18:12', 'Psalms', 18, 12, '&nbsp;د هغۀ د حضور جلال تورې وريځې وشلولې، او ږلۍ او بل سکارۀ يې راورول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13143, 'Psalms 18:13', 'Psalms', 18, 13, '&nbsp;واورېدے شو د آسمانه د مالِک خُدائ آواز، د تندر په شان د خُدائ تعالىٰ راغلو آواز.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13144, 'Psalms 18:14', 'Psalms', 18, 14, '&nbsp;خپل دشمنان يې کړل خوارۀ د غشو په ويشتو سره، و يې زغلول د تندر په ګړزار او په برېښنا سره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13145, 'Psalms 18:15', 'Psalms', 18, 15, '&nbsp;اے مالِکه خُدايه ستا په حُکم او په چغه په رټلو بېخ د سمندر راښکاره شولو، او بنياد د زمکې راڅرګند شولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13146, 'Psalms 18:16', 'Psalms', 18, 16, '&nbsp;د آسمانه يې خپل لاس کړلو راوږد او زۀ يې بچ کړم، زۀ يې د ډوبو اوبو نه رابهر کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13147, 'Psalms 18:17', 'Psalms', 18, 17, '&nbsp;بچ يې کړمه زۀ د زورَور دشمن د لاسه، چې زما نه يې نفرت کولو او وو زما دپاسه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13148, 'Psalms 18:18', 'Psalms', 18, 18, '&nbsp;په ورځ د مصيبت هغوئ کړى راسره جنګونه، خو مالِک خُدائ زما مل وو په خپله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13149, 'Psalms 18:19', 'Psalms', 18, 19, '&nbsp;زۀ يې يو پُراَمنه ځائ ته راوستم، ځکه چې هغه رانه خوشحال وو زۀ يې بچ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13150, 'Psalms 18:20', 'Psalms', 18, 20, '&nbsp;ما ته په ښۀ کولو مالِک اجر راکړے دے، زما د بې‌ګناهۍ په وجه يې ما له انعام راکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13151, 'Psalms 18:21', 'Psalms', 18, 21, '&nbsp;ځکه ما کارونه د مالِک خُدائ پوره کړى دى، نۀ مې بد عمل چرته د خُدائ پاک خلاف کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13152, 'Psalms 18:22', 'Psalms', 18, 22, '&nbsp;ما د هغۀ په ټول قانون عمل کړے دے، پرېښى نۀ دى ما د هغۀ اصُول منلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13153, 'Psalms 18:23', 'Psalms', 18, 23, '&nbsp;د خُدائ په وړاندې زۀ بې‌داغه يم خپل ځان مې د ګناه نه بچ ساتلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13154, 'Psalms 18:24', 'Psalms', 18, 24, '&nbsp;مالِک ما له د ښۀ کولو اجر راکړے دے، هغه ‎پوهيږى چې زۀ بې‌ګناه يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13155, 'Psalms 18:25', 'Psalms', 18, 25, '&nbsp;تۀ د وفادارو سره وفادار يې، تۀ د هغوئ سره نېکى کوې څوک چې نېکان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13156, 'Psalms 18:26', 'Psalms', 18, 26, '&nbsp;پاکانو ته تۀ خپل ځان پاک ښکاره کوې، او هغوئ څوک چې مکاران دى مکر کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13157, 'Psalms 18:27', 'Psalms', 18, 27, '&nbsp;تۀ خلاصون ورکوې عاجزانو له خو تۀ په خپله کبر نسکوروې مغرورانو له.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13158, 'Psalms 18:28', 'Psalms', 18, 28, '&nbsp;اے مالِکه خُدايه، تۀ زما چراغ يې، مالِکه خُدايه، زما تيارۀ په رڼا بدلوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13159, 'Psalms 18:29', 'Psalms', 18, 29, '&nbsp;ستا په مدد زۀ فوجونه تس نس کولے شم، د مالِک خُدائ په مدد د دېوالونو نه دانګلے شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13160, 'Psalms 18:30', 'Psalms', 18, 30, '&nbsp;د خُدائ پاک لاره کامله ده، د مالِک وعده صحيح ده. د هر چا دپاره ډال دے څوک چې د هغۀ غواړى پناه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13161, 'Psalms 18:31', 'Psalms', 18, 31, '&nbsp;د مالِک نه بغېر بل خُدائ څوک دے؟ او زمونږ د خُدائ نه بغېر څوک ګټ دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13162, 'Psalms 18:32', 'Psalms', 18, 32, '&nbsp;دا خُدائ دے چې زور طاقت راکوى ما له پُراَمنه کوى دے په خپله لار ما له.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13163, 'Psalms 18:33', 'Psalms', 18, 33, '&nbsp;هغۀ جوړې کړى زما پښې د هوسۍ د پښو په شان، چې شمه پاس په اوچتو غرونو روان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13164, 'Psalms 18:34', 'Psalms', 18, 34, '&nbsp;هغه تياروى جنګ ته زما لاسونه، چې مټې مې راکاږى د زېړو کمانونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13165, 'Psalms 18:35', 'Psalms', 18, 35, '&nbsp;تا ما له د خلاصون ډال راکړے دے، ستا ښى لاس زما مدد کړے دے، او ستا مدد زما ځان تکړه کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13166, 'Psalms 18:36', 'Psalms', 18, 36, '&nbsp;تا زما د پښو دپاره پراخه لاره جوړه کړله، ترڅو پښې زما ونۀ ښوئيږى هيڅکله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13167, 'Psalms 18:37', 'Psalms', 18, 37, '&nbsp;زۀ په خپل دشمن پسې شوم کړل مې ګرفتار، تر هغې واپس نه شوم ترڅو دوئ مې کړل تار په تار.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13168, 'Psalms 18:38', 'Psalms', 18, 38, '&nbsp;هغوئ مې داسې ووهل چې بيا پاڅېدے نۀ شول، هغوئ زما د پښو د لاندې شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13169, 'Psalms 18:39', 'Psalms', 18, 39, '&nbsp;ما له دې راکړو طاقت د جنګ دپاره، تا دشمنان په پښو کښې وغورزول زما دپاره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13170, 'Psalms 18:40', 'Psalms', 18, 40, '&nbsp;تا دشمنان په تېښته وتښتول زما نه، ما کړل تباه چا چې نفرت کولو زما نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13171, 'Psalms 18:41', 'Psalms', 18, 41, '&nbsp;د بچ کولو يې څوک نۀ وُو هغوئ وکړل د مدد دپاره فريادونه، دوئ وکړو سوال مالِک خُدائ ته خو هغۀ ورنۀ کړو جواب.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13172, 'Psalms 18:42', 'Psalms', 18, 42, '&nbsp;زۀ هغوئ مېده کوم لکه د طوفان دوړې، زۀ يې جارُو کوم لکه د کوڅو خاورې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13173, 'Psalms 18:43', 'Psalms', 18, 43, '&nbsp;زۀ تا بچ کړے د باغيانو يم، مشر کړے دې د قومونو يم، او چې څوک ما نۀ پېژندل هغوئ اوس زما خِدمت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13174, 'Psalms 18:44', 'Psalms', 18, 44, '&nbsp;منى هغوئ زما امر چې کله شى خبر زما، بهرنى قومونه سرونه ټيټوى په وړاندې زما.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13175, 'Psalms 18:45', 'Psalms', 18, 45, '&nbsp;کله چې خبر شى بائيلى خپل همتونه، راځى ما له په ويره رپېدو د مضبوطو قلاګانو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13176, 'Psalms 18:46', 'Psalms', 18, 46, '&nbsp;مالِک خُدائ ژوندے دے، ثنا دې وى زما د پناه ګاه، لوئى دې وى زما د خلاصونکى خُدائ پاک.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13177, 'Psalms 18:47', 'Psalms', 18, 47, '&nbsp;څوک چې راکوى ما له تکليفونه نو د هغوئ نه بدل اخلى زما، هغه خُدائ پاک دے چې قومونه ماتحت کوى زما،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13178, 'Psalms 18:48', 'Psalms', 18, 48, '&nbsp;څوک چې ما د خپلو دشمنانو نه بچ کوى. تا زۀ په خپلو دشمنانو باندې اوچت کړم، او تا زۀ د ظالمانو نه بچ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13179, 'Psalms 18:49', 'Psalms', 18, 49, '&nbsp;ځکه مالِک خُدايه زۀ به ستا ثناء صِفت کوم، ستا د نوم به په قومونو کښې ثناء صِفت کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13180, 'Psalms 18:50', 'Psalms', 18, 50, '&nbsp;مالِک خُدائ ورکوى لوئې فتحې خپل بادشاه له، ورکوى نۀ ختمېدونکې مينه خپل غوره شوى له، د تل دپاره داؤد او د هغۀ ټول اولاد له.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13181, 'Psalms 19:1', 'Psalms', 19, 1, '&nbsp;آسمانونه د خُدائ پاک جلال څومره ښۀ بيانوى، خلا يې د لاس کارنامې صفا بيانوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13182, 'Psalms 19:2', 'Psalms', 19, 2, '&nbsp;هره ورځ بلې ورځ پسې متواتر وېنا کوى، هره شپه بلې شپې پسې د هغۀ مشهورتيا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13183, 'Psalms 19:3', 'Psalms', 19, 3, '&nbsp;نۀ کوى خبرې خو په چپه خولۀ وينا کوى هيڅکله چا نۀ دے اورېدلے آواز يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13184, 'Psalms 19:4', 'Psalms', 19, 4, '&nbsp;خو د هغوئ آواز په ټوله دُنيا کښې اورېدلے شوے وو، او د هغوئ کلام د دُنيا په آخرى حدونو پورې رسېدلے وو. نمر دپاره خُدائ کور جوړ کړے دے پاس په آسمان،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13185, 'Psalms 19:5', 'Psalms', 19, 5, '&nbsp;لکه زلمے چې د خپلې کمرې نه بهر راوځى، لکه څنګه چې يو پهلوان په خوشحالۍ د منډې دپاره ليواله وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13186, 'Psalms 19:6', 'Psalms', 19, 6, '&nbsp;خپله لاره جوړوى په آسمانونو د يو سر نه تر بله. د ګرمۍ نه يې هيڅ څيز پټېدے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13187, 'Psalms 19:7', 'Psalms', 19, 7, '&nbsp;قانون د مالِک خُدائ کامِل دے، روح تازه کوى. هدايت د مالِک خُدائ باورى دے، د ساده نه هوښيار جوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13188, 'Psalms 19:8', 'Psalms', 19, 8, '&nbsp;حُکمونه د مالِک خُدائ رښتيا دى زړۀ خوشحالوى. د مالِک خُدائ حُکمونه پاک دى د ژوند پوهه ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13189, 'Psalms 19:9', 'Psalms', 19, 9, '&nbsp;د مالِک خُدائ يره پاکه ده او تل به وى. حُکمونه د مالِک خُدائ درست دى هر يو په اِنصاف وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13190, 'Psalms 19:10', 'Psalms', 19, 10, '&nbsp;خواهش يې د زرو نه زيات دے، د سوچه زرو نه هم زيات دے، دا د شاتو نه هم ډېر خوږ دے، د هغه شاتو نه چې د ګبين نه راڅاڅى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13191, 'Psalms 19:11', 'Psalms', 19, 11, '&nbsp;دا ما ستا خِدمتګار ته خبرتيا راکوى، هغه څوک يې چې منى لوئ اجر ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13192, 'Psalms 19:12', 'Psalms', 19, 12, '&nbsp;څوک څنګه د خپل زړۀ په ګناه پوهېدے شى؟ ما پاک کړه د پټو خطاګانو نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13193, 'Psalms 19:13', 'Psalms', 19, 13, '&nbsp;د قصداً ګناهونو نه خپل خِدمتګار بچ کړه، چې راباندې غالب نۀ شى ما ترې خلاص کړه. نو داسې زۀ به بچ شمه د جرمونو نه، او بچ به شمه زۀ د لويو ګناهونو نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13194, 'Psalms 19:14', 'Psalms', 19, 14, '&nbsp;زما خبرې او زما د زړۀ خيالونه دې منظور شى تا ته، اے مالِکه خُدايه تۀ يې زما پناه ګاه او زما خلاصونکے يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13195, 'Psalms 20:1', 'Psalms', 20, 1, '&nbsp;په وخت د مصيبت کښې دې مالِک ستا فرياد واورى، د يعقوب د خُدائ پاک نوم دې د هر نقصان نه ستا حفاظت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13196, 'Psalms 20:2', 'Psalms', 20, 2, '&nbsp;هغه دې ستا مدد وکړى د خپل مقدس ځائ نه او داسې به طاقت درکوى د صيون نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13197, 'Psalms 20:3', 'Psalms', 20, 3, '&nbsp;ټولې قربانۍ دې ستا قبولې کړى ټولې سوزېدونکې نذرانې دې ستا منظورې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13198, 'Psalms 20:4', 'Psalms', 20, 4, '&nbsp;هغه دې ستا د زړۀ ارمان پوره کړى کاميابه دې هغه ستا منصوبې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13199, 'Psalms 20:5', 'Psalms', 20, 5, '&nbsp;نو ستا په کاميابۍ به چغې د خوښۍ ووهو د خپل خُدائ د نوم جنډې به اوچتې کړُو. مالِک خُدائ دې جواب درکړى ستا د ټولو سوالونو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13200, 'Psalms 20:6', 'Psalms', 20, 6, '&nbsp;اوس زۀ په دې پوهېږم چې مالِک خُدائ به خپل غوره شوے بادشاه بچ کړى، هغه به د خپل پاک آسمان نه جواب ورکړى په خپل لوئ طاقت سره به يې هغه بچ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');